def darken_hex(hex_color: str, percentage: float) -> str:
    """
    Darken a hex color by a percentage.

    Args:
        hex_color: Color such as "#6699CC" or "6699CC".
        percentage: Amount to darken, from 0 to 100.

    Returns:
        The darkened color as a six-digit hex string.
    """
    if not 0 <= percentage <= 100:
        raise ValueError("percentage must be between 0 and 100")

    hex_color = hex_color.lstrip("#")

    if len(hex_color) != 6:
        raise ValueError("hex_color must contain exactly 6 hexadecimal digits")

    try:
        red, green, blue = (
            int(hex_color[i:i + 2], 16)
            for i in (0, 2, 4)
        )
    except ValueError:
        raise ValueError("hex_color contains invalid hexadecimal characters")

    factor = 1 - percentage / 100

    darkened = (
        round(red * factor),
        round(green * factor),
        round(blue * factor),
    )

    return "#{:02X}{:02X}{:02X}".format(*darkened)


