print(darken_hex("#6699CC", 25))  # #4D7399

from __future__ import annotations

from dataclasses import MISSING, fields, is_dataclass
from typing import Any, TypeVar, get_args, get_origin, get_type_hints

T = TypeVar("T")


class RequestValidationError(ValueError):
    """Raised when a request body cannot be parsed into the requested model."""

    def __init__(self, errors: dict[str, str]):
        self.errors = errors
        message = "; ".join(f"{field}: {error}" for field, error in errors.items())
        super().__init__(message)


def parse_request_body(body: Any, model: type[T]) -> T:
    """
    Validate and convert a request body into a typed dataclass model.

    The model must be a dataclass. Unknown fields and invalid values raise
    RequestValidationError.
    """
    if not is_dataclass(model):
        raise TypeError("model must be a dataclass type")

    if not isinstance(body, dict):
        raise RequestValidationError(
            {"body": "expected an object"}
        )

    hints = get_type_hints(model)
    model_fields = {field.name: field for field in fields(model)}
    errors: dict[str, str] = {}

    unknown = set(body) - set(model_fields)
    for name in sorted(unknown):
        errors[name] = "unexpected field"

    values: dict[str, Any] = {}

    for name, field in model_fields.items():
        if name not in body:
            if field.default is not MISSING or field.default_factory is not MISSING:
                continue
            errors[name] = "field is required"
            continue

        try:
            values[name] = _convert_value(body[name], hints.get(name, Any), name)
        except ValueError as exc:
            errors[name] = str(exc)

    if errors:
        raise RequestValidationError(errors)

    try:
        return model(**values)
    except TypeError as exc:
        raise RequestValidationError({"body": str(exc)}) from exc


def _convert_value(value: Any, annotation: Any, field_name: str) -> Any:
    if annotation is Any:
        return value

    origin = get_origin(annotation)
    args = get_args(annotation)

    if origin is None:
        if annotation is type(None):
            if value is not None:
                raise ValueError("must be null")
            return None

        if annotation is bool:
            if not isinstance(value, bool):
                raise ValueError("must be a boolean")
            return value

        if annotation is int:
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError("must be an integer")
            return value

        if annotation is float:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("must be a number")
            return float(value)

        if annotation is str:
            if not isinstance(value, str):
                raise ValueError("must be a string")
            return value

        if is_dataclass(annotation):
            return parse_request_body(value, annotation)

        if isinstance(value, annotation):
            return value

        raise ValueError(f"has invalid type; expected {annotation}")

    if origin is list:
        if not isinstance(value, list):
            raise ValueError("must be a list")
        item_type = args[0] if args else Any
        return [
            _convert_value(item, item_type, f"{field_name}[{index}]")
            for index, item in enumerate(value)
        ]

    if origin is dict:
        if not isinstance(value, dict):
            raise ValueError("must be an object")
        key_type, value_type = args or (Any, Any)
        converted = {}
        for key, item in value.items():
            converted_key = _convert_value(key, key_type, field_name)
            converted[converted_key] = _convert_value(item, value_type, field_name)
        return converted

    if origin is tuple:
        if not isinstance(value, (list, tuple)):
            raise ValueError("must be an array")
        if args and len(args) == len(value):
            return tuple(
                _convert_value(item, item_type, field_name)
                for item, item_type in zip(value, args)
            )
        return tuple(value)

    # Supports Optional[T] and other Union types.
    if origin is __import__("types").UnionType or str(origin) == "typing.Union":
        for option in args:
            if option is type(None) and value is None:
                return None
            try:
                return _convert_value(value, option, field_name)
            except ValueError:
                continue
        raise ValueError("has an invalid value")

    raise ValueError(f"unsupported type annotation: {annotation}")

