from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence
from typing import Any


def format_table(
    records: Iterable[Mapping[str, Any] | Sequence[Any]],
    headers: Sequence[str] | None = None,
) -> str:
    """Return records formatted as an aligned plain-text table.

    Records may be mappings or sequences. Mapping keys are used as headers;
    sequence records require ``headers``.
    """
    rows = list(records)

    if not rows:
        return ""

    if headers is None:
        if not isinstance(rows[0], Mapping):
            raise ValueError("headers are required for sequence records")
        headers = list(rows[0].keys())
    else:
        headers = list(headers)

    values: list[list[str]] = []

    for record in rows:
        if isinstance(record, Mapping):
            row = [str(record.get(header, "")) for header in headers]
        else:
            if len(record) != len(headers):
                raise ValueError("record length does not match headers")
            row = [str(value) for value in record]
        values.append(row)

    widths = [
        max(len(str(header)), *(len(row[index]) for row in values))
        for index, header in enumerate(headers)
    ]

    lines = [
        "  ".join(str(header).ljust(width) for header, width in zip(headers, widths)),
        "  ".join("-" * width for width in widths),
    ]

    lines.extend(
        "  ".join(value.ljust(width) for value, width in zip(row, widths))
        for row in values
    )

    return "\n".join(lines)


def print_table(
    records: Iterable[Mapping[str, Any] | Sequence[Any]],
    headers: Sequence[str] | None = None,
) -> None:
    """Print records as an aligned plain-text table."""
    table = format_table(records, headers=headers)
    if table:
        print(table)

