from pathlib import Path


def read_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Return ``key`` from a .env file, or ``default`` when it is missing.

    Supports simple ``KEY=value`` entries, optional quotes, blank lines, and
    comments. Values may contain ``=`` characters.
    """
    path = Path(env_file)

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line[7:].lstrip()

        if "=" not in line:
            continue

        name, value = line.split("=", 1)

        if name.strip() != key:
            continue

        value = value.strip()

        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]

        return value

    return default

