def verify_and_upgrade(stored_hash: str, password: str) -> tuple[bool, str | None]:
    try:
        valid = ph.verify(stored_hash, password)
    except (VerifyMismatchError, VerificationError):
        return False, None

    if valid and ph.check_needs_rehash(stored_hash):
        return True, ph.hash(password)

    return True, None

