@app.post("/phone/validate", response_model=PhoneNumberResponse)
def validate_phone_number(payload: PhoneNumberRequest) -> PhoneNumberResponse:
    phone = payload.phone_number.strip()

    if not phone:
        raise HTTPException(
            status_code=400,
            detail="Phone number must not be empty",
        )

    region = payload.default_region.upper() if payload.default_region else None

    if region is not None and (
        len(region) != 2 or not region.isalpha()
    ):
        raise HTTPException(
            status_code=400,
            detail="default_region must be a two-letter ISO country code",
        )

    try:
        parsed_number = phonenumbers.parse(phone, region)
    except NumberParseException as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid phone number format: {exc}",
        ) from exc

    if not phonenumbers.is_valid_number(parsed_number):
        return PhoneNumberResponse(valid=False)

    return PhoneNumberResponse(
        valid=True,
        international=phonenumbers.format_number(
            parsed_number,
            phonenumbers.PhoneNumberFormat.E164,
        ),
        country_code=parsed_number.country_code,
        national_number=str(parsed_number.national_number),
    )

