)

def normalize_phone(value: str, default_region: str | None = None) -> str:
    """
    Return a valid phone number in E.164 format.
    Example: "+1 415 555 2671" -> "+14155552671"

    default_region is an ISO 3166-1 alpha-2 code, e.g. "US", "GB".
    It is required when value is not written with an international + prefix.
    """
    value = value.strip()

    try:
        number = phonenumbers.parse(value, default_region)
    except NumberParseException as exc:
        raise ValueError(f"Invalid phone number format: {exc}") from exc

    if not is_possible_number(number):
        raise ValueError("Phone number has an impossible length or prefix")

    if not is_valid_number(number):
        raise ValueError("Phone number is not valid for its region")

    return format_number(number, PhoneNumberFormat.E164)

