) -> tuple[str | None, str | None]:
    """
    Extract the sender and subject from a raw email message.

    Returns:
        A tuple of ``(sender, subject)``. Missing headers are returned as None.

    Raises:
        TypeError: If raw_message is neither bytes nor str.
    """
    if isinstance(raw_message, bytes):
        message: Message = BytesParser(policy=policy.default).parsebytes(raw_message)
    elif isinstance(raw_message, str):
