import json
from dataclasses import MISSING, fields, is_dataclass
from types import UnionType
from typing import Any, TypeVar, Union, get_args, get_origin, get_type_hints


T = TypeVar("T")


class RequestBodyError(ValueError):
    """Raised when a request body cannot be parsed or validated."""


def parse_request_body(body: str | bytes, model: type[T]) -> T:
    """Parse and validate a JSON request body into ``model``.

    Args:
        body: UTF-8 JSON text or bytes.
        model: A dataclass type describing the expected request body.

    Returns:
        An instance of ``model``.

    Raises:
        RequestBodyError: If the body is invalid JSON or does not match
            the requested model.
    """
    try:
        if isinstance(body, bytes):
            body = body.decode("utf-8")

        data = json.loads(body)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RequestBodyError(f"Invalid JSON request body: {exc}") from exc

    try:
        return _convert_value(data, model, path="$")
    except RequestBodyError:
        raise
    except Exception as exc:
        raise RequestBodyError(f"Invalid request body: {exc}") from exc


def _convert_value(value: Any, expected: Any, *, path: str) -> Any:
    origin = get_origin(expected)
    args = get_args(expected)

    if expected is Any:
        return value

    if origin in (Union, UnionType):
        errors: list[str] = []

        for option in args:
            if option is type(None) and value is None:
                return None

            try:
                return _convert_value(value, option, path=path)
            except RequestBodyError as exc:
                errors.append(str(exc))

        expected_name = " | ".join(_type_name(option) for option in args)
        raise RequestBodyError(
            f"{path}: expected {expected_name}, got {_type_name(type(value))}"
        )

    if value is None:
        raise RequestBodyError(
            f"{path}: expected {_type_name(expected)}, got null"
        )

    if is_dataclass(expected):
        return _convert_dataclass(value, expected, path=path)

    if origin is list:
        if not isinstance(value, list):
            raise RequestBodyError(f"{path}: expected list, got {_type_name(type(value))}")

        item_type = args[0] if args else Any
        return [
            _convert_value(item, item_type, path=f"{path}[{index}]")
            for index, item in enumerate(value)
        ]

    if origin is dict:
        if not isinstance(value, dict):
            raise RequestBodyError(
                f"{path}: expected object, got {_type_name(type(value))}"
            )

        key_type, value_type = args or (Any, Any)
        converted: dict[Any, Any] = {}

        for key, item in value.items():
            converted_key = _convert_value(key, key_type, path=f"{path}.<key>")
            converted[converted_key] = _convert_value(
                item,
                value_type,
                path=f"{path}.{key}",
            )

        return converted

    if expected is bool:
        if not isinstance(value, bool):
            raise RequestBodyError(f"{path}: expected bool, got {_type_name(type(value))}")
        return value

    if expected is int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise RequestBodyError(f"{path}: expected int, got {_type_name(type(value))}")
        return value

    if expected is float:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise RequestBodyError(
                f"{path}: expected float, got {_type_name(type(value))}"
            )
        return float(value)

    if expected is str:
        if not isinstance(value, str):
            raise RequestBodyError(f"{path}: expected str, got {_type_name(type(value))}")
        return value

    if expected is type(None):
        if value is not None:
            raise RequestBodyError(f"{path}: expected null, got {_type_name(type(value))}")
        return None

    if isinstance(expected, type) and isinstance(value, expected):
        return value

    raise RequestBodyError(
        f"{path}: expected {_type_name(expected)}, got {_type_name(type(value))}"
    )


def _convert_dataclass(value: Any, model: type[T], *, path: str) -> T:
    if not isinstance(value, dict):
        raise RequestBodyError(
            f"{path}: expected object, got {_type_name(type(value))}"
        )

    hints = get_type_hints(model)
    model_fields = {field.name: field for field in fields(model)}

    unknown_fields = set(value) - model_fields.keys()
    if unknown_fields:
        names = ", ".join(sorted(unknown_fields))
        raise RequestBodyError(f"{path}: unexpected field(s): {names}")

    converted: dict[str, Any] = {}

    for name, field in model_fields.items():
        field_path = f"{path}.{name}"

        if name not in value:
            if field.default is not MISSING or field.default_factory is not MISSING:
                continue

            raise RequestBodyError(f"{field_path}: missing required field")

        converted[name] = _convert_value(
            value[name],
            hints.get(name, field.type),
            path=field_path,
        )

    return model(**converted)


def _type_name(value: Any) -> str:
    if isinstance(value, type):
        return value.__name__
    return str(value)

