from pathlib import Path


def get_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Return a value from a .env file, or ``default`` if it is missing.

    Supports simple entries such as:

        API_KEY=secret
        API_URL="https://example.com"
        DEBUG='true'

    Existing environment variables take precedence over values in the file.
    """
    import os

    if key in os.environ:
        return os.environ[key]

    path = Path(env_file)

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line[7:].lstrip()

        name, separator, value = line.partition("=")

        if separator and name.strip() == key:
            value = value.strip()

            if len(value) >= 2 and value[0] == value[-1]:
                if value[0] in {"'", '"'}:
                    value = value[1:-1]

            return value

    return default

import re


def phone(value: str, default_region: str = "US") -> str:
    """Validate and format a phone number in international format.

    The formatter accepts common separators and formatting characters.
    Numbers with a leading '+' are treated as already international.
    National numbers are interpreted using ``default_region``.

    This lightweight implementation validates structure but does not attempt
    country-specific numbering-plan validation.
    """
    if not isinstance(value, str):
        raise ValueError("phone number must be text")

    raw = value.strip()
    if not raw:
        raise ValueError("phone number cannot be empty")

    default_region = default_region.strip().upper()
    if not re.fullmatch(r"[A-Z]{2}", default_region):
        raise ValueError("default region must be a two-letter country code")

    if raw.startswith("+"):
        digits = re.sub(r"\D", "", raw[1:])
        if not digits:
            raise ValueError("phone number contains no digits")
        international = f"+{digits}"
    else:
        digits = re.sub(r"\D", "", raw)
        if not digits:
            raise ValueError("phone number contains no digits")

        # Support common North American national numbers.
        if default_region == "US":
            if len(digits) == 10:
                international = f"+1{digits}"
            elif len(digits) == 11 and digits.startswith("1"):
                international = f"+{digits}"
            else:
                raise ValueError(
                    "US phone numbers must contain 10 digits, "
                    "or 11 digits beginning with 1"
                )
        else:
            raise ValueError(
                "national-number formatting currently supports only US numbers; "
                "provide an international number beginning with '+'"
            )

    # Basic international-number validation.
    number_digits = international[1:]
    if not 7 <= len(number_digits) <= 15:
        raise ValueError("phone number must contain between 7 and 15 digits")

    return international

