from collections.abc import Iterable, Mapping, Sequence
from typing import Any


def print_table(
    records: Iterable[Mapping[str, Any] | Sequence[Any]],
    headers: Sequence[str] | None = None,
) -> None:
    """Print records as an aligned table in the terminal.

    Records may be mappings or sequences. For mappings, keys are used as
    headers unless ``headers`` is provided.
    """
    rows = list(records)

    if not rows:
        if headers:
            print(" | ".join(str(header) for header in headers))
        return

    if isinstance(rows[0], Mapping):
        if headers is None:
            headers = list(rows[0].keys())

        data = [
            [record.get(header, "") for header in headers]  # type: ignore[union-attr]
            for record in rows
        ]
    else:
        data = [list(record) for record in rows]

        if headers is None:
            headers = [f"Column {index + 1}" for index in range(len(data[0]))]

    header_values = [str(header) for header in headers]
    string_rows = [
        [str(value) if value is not None else "" for value in row]
        for row in data
    ]

    widths = [
        max(
            len(header_values[index]),
            *(len(row[index]) for row in string_rows),
        )
        for index in range(len(header_values))
    ]

    def format_row(row: Sequence[str]) -> str:
        return " | ".join(
            value.ljust(widths[index]) for index, value in enumerate(row)
        )

    separator = "-+-".join("-" * width for width in widths)

    print(format_row(header_values))
    print(separator)

    for row in string_rows:
        print(format_row(row))

