def closest_match(query: str, names: Iterable[str]) -> str | None:
    """
    Return the name most similar to query, or None if names is empty.
    Matching is case-insensitive and ignores surrounding whitespace.
    """
    candidates = list(names)

    if not candidates:
        return None

    normalized_query = query.strip().casefold()

    return max(
        candidates,
        key=lambda name: SequenceMatcher(
            None,
            normalized_query,
            name.strip().casefold(),
        ).ratio(),
    )


