from __future__ import annotations

from collections.abc import Callable
from functools import wraps
from threading import RLock
from time import monotonic
from typing import Any, ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")


def ttl_cache(
    ttl: float,
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    """Cache function results for ``ttl`` seconds.

    Cache entries are keyed by positional and keyword arguments. Exceptions
    are not cached. A non-positive TTL disables caching.
    """
    if ttl < 0:
        raise ValueError("ttl must be non-negative")

    def decorator(function: Callable[P, R]) -> Callable[P, R]:
        cache: dict[tuple[Any, ...], tuple[float, R]] = {}
        lock = RLock()

        def make_key(args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[Any, ...]:
            try:
                return args + (object(),) + tuple(sorted(kwargs.items()))
            except TypeError as exc:
                raise TypeError(
                    f"{function.__name__} arguments must be hashable"
                ) from exc

        @wraps(function)
        def wrapped(*args: P.args, **kwargs: P.kwargs) -> R:
            if ttl == 0:
                return function(*args, **kwargs)

            key = make_key(args, kwargs)
            now = monotonic()

            with lock:
                cached = cache.get(key)
                if cached is not None:
                    expires_at, value = cached
                    if now < expires_at:
                        return value
                    del cache[key]

            value = function(*args, **kwargs)

            with lock:
                cache[key] = (monotonic() + ttl, value)

            return value

        def cache_clear() -> None:
            """Clear all cached results."""
            with lock:
                cache.clear()

        wrapped.cache_clear = cache_clear  # type: ignore[attr-defined]
        return wrapped

    return decorator

