from functools import lru_cache
from time import monotonic
from typing import Any, Callable

def ttl_cache(ttl_seconds: float, maxsize: int = 128):
    def decorator(func: Callable):
        @lru_cache(maxsize=maxsize)
        def cached(*args, _expires_at, **kwargs):
            return func(*args, **kwargs)

        def wrapper(*args, **kwargs):
            now = monotonic()
            key = (args, tuple(sorted(kwargs.items())))

            # Keep expiration metadata separate from the cached result.
            expires_at = expirations.get(key, 0)

            if now >= expires_at:
                expires_at = now + ttl_seconds
                expirations[key] = expires_at

            return cached(*args, _expires_at=expires_at, **kwargs)

        expirations = {}
        wrapper.cache_clear = cached.cache_clear
        return wrapper

    return decorator

