from __future__ import annotations

from pathlib import Path


def read_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Read a value from a .env file.

    Supports simple KEY=value entries, optional quoting, comments, and blank
    lines. Returns ``default`` when the file or key is missing.
    """
    path = Path(env_file)

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line[7:].lstrip()

        if "=" not in line:
            continue

        name, value = line.split("=", 1)

        if name.strip() != key:
            continue

        value = value.strip()

        if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
            value = value[1:-1]

        return value

    return default
